// Strip control characters. Descriptions keep single line breaks.
const cleanLine = (v) => typeof v === 'string' ? v.replace(/[\u0000-\u001F\u007F-\u009F]/g, ' ').replace(/\s+/g, ' ').trim() : '';
const cleanText = (v) => typeof v === 'string'
  ? v.replace(/\r\n?/g, '\n').replace(/[\u0000-\u0009\u000B-\u001F\u007F-\u009F]/g, '').replace(/\n{3,}/g, '\n\n').trim()
  : '';
const len = (s) => [...s].length; // count characters, not UTF-16 units
const fail = (message) => [{ json: { valid: false, error: { code: 'VALIDATION', message } } }];
const raw = $input.first().json.body;
const body = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};

const LANGUAGES = ['en', 'zh', 'ms', 'ta'];
const sessionId = typeof body.sessionId === 'string' ? body.sessionId.trim() : '';
const message = cleanText(body.message);
const languageRaw = typeof body.language === 'string' ? body.language.trim().toLowerCase() : '';
const language = languageRaw || 'en';

if (!sessionId) return fail('The chat session is missing. Please reload the page and try again.');
if (len(sessionId) > 64 || !/^[A-Za-z0-9_-]+$/.test(sessionId)) return fail('The chat session is not valid. Please reload the page and try again.');
if (!message) return fail('Please type a question first.');
if (len(message) > 500) return fail('Your message is too long. Please use 500 characters or fewer.');
if (!LANGUAGES.includes(language)) return fail('That language is not supported yet. Please use en, zh, ms or ta.');

return [{ json: { valid: true, sessionId, message, language } }];

// The AI Agent's answer is in "output". We asked for JSON, but parse defensively.
const raw = String($input.first().json.output ?? '');
const visitorMessage = String($('Validate Input').first().json.message || '');
const FALLBACK = "Sorry, I am not sure about that. Please ask a museum staff member, or use the Help page in this guide.";

let reply = '';
let suggestStaff = false;
const match = raw.match(/\{[\s\S]*\}/);
try {
  const parsed = JSON.parse(match ? match[0] : raw);
  reply = typeof parsed.reply === 'string' ? parsed.reply.trim() : '';
  suggestStaff = parsed.suggestStaff === true;
} catch (e) {
  reply = raw.replace(/```(json)?/gi, '').trim();
  suggestStaff = true;
}
if (!reply) { reply = FALLBACK; suggestStaff = true; }

// Safety net: always offer staff help for possible emergencies, whatever the model said.
// English, Chinese, Malay and Tamil keywords.
const EMERGENCY = /(emergenc|hurt|injur|bleed|fire|smoke|faint|breath|lost (my )?(child|kid|son|daughter|mum|mom|dad|parent)|missing|ambulance|police|unwell|sick|pain|danger|accident|救命|紧急|緊急|受伤|受傷|流血|着火|火灾|火災|烟|煙|晕倒|暈倒|走失|迷路|不见了|不見了|救护车|救護車|报警|報警|危险|危險|kecemasan|cedera|luka|berdarah|kebakaran|asap|pengsan|hilang|sesat|ambulans|polis|bahaya|அவசர|காயம்|இரத்த|தீப்பிடி|புகை|மயக்க|காணவில்லை|ஆம்புலன்ஸ்|காவல்|ஆபத்து|உதவி)/i;
if (EMERGENCY.test(visitorMessage)) suggestStaff = true;

if ([...reply].length > 1500) reply = [...reply].slice(0, 1500).join('') + '...';
return [{ json: { reply, suggestStaff } }];
